#!/usr/bin/env python3
# In a notebook, do not edit this file. It is generic - the template's, listed
# in .claude/notebook/manifest.txt - and the update skill replaces it; the
# notebook's pre-commit hook refuses a commit that changes it. To extend:
#   - a setting or an audit rule: .scripts/notebook_config.py
#   - an operation or a check of the notebook's own: a script of its own in
#     .scripts/ that imports this one, never a copy of it
#   - a rule for one type: that type's declaration in Types/
#   - a fix every notebook needs: ask the template for it, with an issue -
#     .claude/notebook/requests.md
# The whole table: .claude/notebook/upstream.md, "The outlets".
"""Turn plain-text entity mentions into [[links]].

A name written as prose is a reference to that entity, so it should be a
link: the relationship is real, and leaving it as text throws it away.
Obsidian then has the edge, backlinks populate, and connectivity becomes
something you can measure rather than guess.

  relink.py            dry run - count what it would link
  relink.py --report   the names check: what reaches an entity and what does not
  relink.py --apply    write the links

Safety rails, each one load-bearing:
  - scoped to the vault this script lives in, derived from its own path.
  - a name claimed by more than one page is REFUSED, never guessed. See
    .claude/notebook/reference-layer.md: an alias denotes one entity, and
    picking silently is the failure that rule exists to prevent.
  - never touches a verbatim page - one whose type declares `sections: []`
    (registry.md) - or a page in NOT_OURS.
  - skips frontmatter, code fences, headings, blockquotes and existing
    links, so a name inside one is left alone.
  - inside a table row the alias pipe is escaped, because a bare | splits
    the row into extra columns, which silently truncates its last cell.
  - one link per entity per page, at the first mention.
  - GENERIC holds names too common to match safely in prose: a place named
    for what it is would otherwise match half the vault.

Aliases link as [[Real name|the alias]], so the rendered text does not
change - which is what keeps a quoted title quoted.

A group field (GROUP_FIELDS in notebook_config.py) is deliberately NOT
linked. Its names denote a *group* - five pages sharing one are a set, not an
ambiguity - and in prose such a name is usually already part of a linked
full name, so a link would read badly. --report lists them so they stay
visible; the group's view is how they are actually queried.

Idempotent: a page that already links to an entity is left alone, so one
mention becomes a link and the rest stay prose. Without that guard each
re-run finds the next occurrence, because the previous one is now a
protected span, and eventually every mention is a link.
"""
import os, re, sys, collections

# `python3 -I` isolates sys.path, which drops this script's own directory -
# so the config beside it is not importable without putting it back.
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import notebook_config
import notebook

# Derived, not hardcoded - see the note in vault_check.py.
NOTES = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(NOTES)

APPLY = "--apply" in sys.argv

pages, owners, group_owners, ambiguous_owners, common_owners = {}, {}, {}, {}, {}
for dp, dn, fn in os.walk("."):
    dn[:] = [d for d in dn if not d.startswith(".")]
    for f in fn:
        if not f.endswith(".md"): continue
        rel = os.path.join(dp, f)[2:]
        t = open(rel, encoding="utf-8").read()
        pages[rel] = t
        owners.setdefault(f[:-3], set()).add(rel)
        m = re.match(r"---\n(.*?)\n---", t, re.S)
        if m:
            fm = m.group(1) + "\n"
            for key, bucket in ([("aliases", owners)]
                                + [(g, group_owners) for g in notebook_config.GROUP_FIELDS]
                                + [("ambiguous_names", ambiguous_owners),
                                   ("common_names", common_owners)]):
                b = re.search(rf"^{key}:[ \t]*\n((?:[ \t]*-[ \t]*\S.*\n?)+)", fm, re.M)
                if not b: continue
                for line in b.group(1).splitlines():
                    a = line.strip().lstrip("-").strip().strip("\"'")
                    if a: bucket.setdefault(a, set()).add(rel)

# Declared ambiguous on two or more pages: never a candidate, whatever else
# claims it. The entry says "this word means one of us", so resolving it would
# answer a question the notes are deliberately leaving open.
AMBIGUOUS = {n for n, ps in ambiguous_owners.items() if len(ps) > 1}
UNDER_DECLARED = {n: sorted(ps) for n, ps in ambiguous_owners.items() if len(ps) < 2}

# One owner means the name denotes one entity and may be linked. More than one
# and it is refused: two folders holding the same basename is deliberate here,
# and the contract says write the path by hand rather than let a tool choose.
names = {n: next(iter(ps)) for n, ps in owners.items() if len(ps) == 1}
CONTESTED = {n: sorted(ps) for n, ps in owners.items() if len(ps) > 1}

# The glossary, read from `common_names:` on the entities rather than held
# here. A word in it is ordinary vocabulary in this domain, so an occurrence
# is not evidence of a reference - see .claude/notebook/reference-layer.md.
# A word naming no page and no alias needs no entry: it can never be a
# candidate in the first place.
GENERIC = set(common_owners)

# Never edit verbatim text, nor the docs about the notes - and never link TO
# them either. A generated page's name is often ordinary vocabulary or a
# structural marker: an inference marker like `My synthesis:` would match a page named
# after it, so making that page a target would rewrite the epistemic markers
# into links. A converter may not touch a page it does not own, in either
# direction. See .claude/notebook/contract.md law 8.
NOT_A_PAGE_WE_TOUCH = notebook_config.NOT_OURS
# Machinery: a top-level folder of it, and below the top a page whose own type
# is a ledger or generated - an owner holds those in folders of their own, and a
# page an entry owns sits inside the ledger's folder without being a log
# (graph.md, "Ownership").
MACHINERY = notebook.machinery()
_reg = notebook.registry()
MACHINERY_PAGES = {str(p.relative_to(notebook.VAULT)) for t, p in notebook.pages()
                   if t in _reg and (_reg[t]["ledger"] or _reg[t]["generated"] == "true")}

# Verbatim texts: pages of a type declared `sections: []` (registry.md). They
# keep the text exactly as written, so a converter never adds a link to one.
VERBATIM = {t for t, d in notebook.registry().items() if d["sections"] == []}
VERBATIM_PAGES = {rel for rel, t in pages.items()
                  if (m := re.match(r"---\n(?:.*\n)*?type:[ \t]*(\S+)", t)) and m.group(1) in VERBATIM}

def skip(rel):
    b = os.path.basename(rel)
    # The ledger is a record, not a knowledge page. Beyond being append-only
    # (ledger.md law 1), rewriting a closed entry changes its git diff - and
    # one commit per occasion, readable as "what changed then", is a designed
    # feature. Capture links an entry as it writes it; nothing backfills one.
    return (b in NOT_A_PAGE_WE_TOUCH or rel in VERBATIM_PAGES
            or rel.split(os.sep)[0] in MACHINERY or rel in MACHINERY_PAGES)
    # Note this is a SOURCE rule - a tool does not edit machinery. It is not
    # how the type pages avoid being linked TO: every type name is a common
    # noun by construction, so each one declares `common_names:` like any
    # other entity whose name is an ordinary word. A folder rule here would
    # have been a special case standing in for the mechanism.

# >= 4, not > 4: in the notebook this grew from, the old floor silently
# skipped every four-letter alias, and dozens of four-letter names went unlinked.
cands = sorted((n for n in names if n not in GENERIC and n not in AMBIGUOUS
                and len(n) >= 4 and not skip(names[n])), key=len, reverse=True)
REPORT = "--report" in sys.argv

def protected_spans(t):
    spans = []
    for m in re.finditer(r"^---\n.*?\n---\n", t, re.S):        spans.append(m.span())
    for m in re.finditer(r"```.*?```", t, re.S):               spans.append(m.span())
    for m in re.finditer(r"!?\[\[.*?\]\]", t, re.S):           spans.append(m.span())
    for m in re.finditer(r"^#{1,6} .*$", t, re.M):             spans.append(m.span())
    for m in re.finditer(r"^>.*$", t, re.M):                   spans.append(m.span())  # quoted
    return spans

changed_files = 0
total_links = 0
report = collections.defaultdict(list)

for rel, t in sorted(pages.items()):
    if skip(rel): continue
    self_stem = os.path.basename(rel)[:-3]
    done = set()
    out = t
    # Already-linked targets on this page: linking a second mention of the
    # same thing adds noise, and without this a re-run keeps finding the
    # next occurrence until every mention is a link.
    linked_here = set()
    for m in re.finditer(r"!?\[\[(.+?)\]\]", t, re.S):
        inner = m.group(1)
        for sep in ("\\|", "|"):
            if sep in inner:
                inner = inner.split(sep, 1)[0]
                break
        linked_here.add(inner.rstrip("\\").split("#", 1)[0].strip())

    for n in cands:
        if names[n] == rel or n == self_stem or n in done: continue
        if os.path.basename(names[n])[:-3] in linked_here: continue
        spans = protected_spans(out)
        # Case-insensitive: a person's name is always capitalised, so page name
        # and prose form agree - but "the garden hose" mid-sentence never
        # matches `Garden hose`, which is why common nouns stayed unlinked. Safe
        # only because the glossary above holds the words that are ordinary.
        for m in re.finditer(r"(?<![\w'\[|])" + re.escape(n) + r"(?![\w'\]])", out,
                             re.IGNORECASE):
            if any(s <= m.start() < e for s, e in spans): continue
            target = os.path.basename(names[n])[:-3]
            as_written = m.group(0)          # keeps the prose's own capitalisation
            line_start = out.rfind("\n", 0, m.start()) + 1
            in_table = out[line_start:line_start+1] == "|"
            if target == as_written:
                repl = f"[[{as_written}]]"
            else:
                bar = "\\|" if in_table else "|"
                repl = f"[[{target}{bar}{as_written}]]"
            out = out[:m.start()] + repl + out[m.end():]
            done.add(n)
            total_links += 1
            report[rel].append(n)
            break
    if out != t:
        changed_files += 1
        if APPLY:
            open(rel, "w", encoding="utf-8").write(out)

print(f"{'APPLIED' if APPLY else 'DRY RUN'}: {total_links} links across {changed_files} files")
for rel in sorted(report, key=lambda r: -len(report[r]))[:6]:
    print(f"  {rel}: {len(report[rel])}")

if REPORT:
    # The names check: the three classes in .claude/notebook/reference-layer.md.
    by_name = collections.Counter(n for ns in report.values() for n in ns)
    print(f"\n== 1. names that reach one entity ({len(by_name)} of them, {sum(by_name.values())} links) ==")
    for n, c in by_name.most_common(12):
        print(f"  {c:4d} pages  {n:30s} -> {os.path.basename(names[n])[:-3]}")

    print(f"\n== 2. REFUSED: claimed by more than one page ({len(CONTESTED)}) ==")
    for n, ps in sorted(CONTESTED.items()):
        print(f"  {n:46s} {', '.join(ps)}")
    if CONTESTED:
        print("  -> write the path by hand: [[Folder/Name|Name]]. Never let a tool choose.")

    seen = collections.Counter()
    for rel, t in pages.items():
        if skip(rel): continue
        body = re.sub(r"!?\[\[.*?\]\]", " ", t, flags=re.S)
        for g in group_owners:
            if re.search(r"(?<![\w'])" + re.escape(g) + r"(?![\w'])", body):
                seen[g] += 1
    print(f"\n== 3. group names in prose, reported not linked ({len(seen)}) ==")
    for g, c in seen.most_common(10):
        print(f"  {c:4d} pages  {g:30s} {len(group_owners[g])} members")
    print("  -> a group name denotes a set, not one member. Query the group's view.")

    amb_hits = collections.Counter()
    for rel, t in pages.items():
        if skip(rel): continue
        body = re.sub(r"!?\[\[.*?\]\]", " ", t, flags=re.S)
        for n in AMBIGUOUS:
            c = len(re.findall(r"(?<![\w'])" + re.escape(n) + r"(?:'s)?(?![\w'])", body))
            if c: amb_hits[n] += c
    print(f"\n== 4. AMBIGUOUS: ask, never pick ({len(AMBIGUOUS)}) ==")
    for n in sorted(AMBIGUOUS):
        print(f"  {amb_hits[n]:4d} mentions  {n:20s} one of: "
              f"{', '.join(os.path.basename(x)[:-3] for x in sorted(ambiguous_owners[n]))}")
    if AMBIGUOUS:
        print("  -> these are NOT converted. Which one is meant is the user's to say.")
    # A wrong glossary entry is invisible: the entity is simply never linked
    # and nothing breaks. Prompt the re-reading; it cannot be decided here.
    sus = []
    for g in sorted(GENERIC):
        tgt = next(iter(common_owners[g]))
        if skip(tgt):
            continue
        stem = os.path.basename(tgt)[:-3]
        # The signal is the RATIO, not the volume. An ordinary word is mentioned
        # everywhere and linked almost never - correctly generic. A word people
        # keep linking anyway is one the glossary is fighting.
        mention = inbound = 0
        for rel, t in pages.items():
            if skip(rel):
                continue
            body = re.sub(r"!?\[\[.*?\]\]", " ", t, flags=re.S)
            if re.search(r"(?<![\w'])" + re.escape(g) + r"(?:'s)?(?![\w'])", body, re.I):
                mention += 1
            if re.search(r"\[\[[^\]]*" + re.escape(stem) + r"(\||\]\])", t):
                inbound += 1
        tot = mention + inbound
        if tot >= 6 and inbound / tot >= 0.4:
            sus.append((round(inbound / tot, 2), inbound, mention, g, stem))
    if sus:
        print(f"\n== 5. glossary entries worth re-reading ({len(sus)}) ==")
        for ratio, inbound, mention, g, stem in sorted(sus, reverse=True)[:8]:
            print(f"  {ratio:.0%} linked anyway  ({inbound} link / {mention} mention)   {g:18s} -> {stem}")
        print("  -> listed as an ordinary word, yet other pages link the entity. If its")
        print("     occurrences mostly DO refer to it, it is an alias, not a common noun.")

    if UNDER_DECLARED:
        print(f"\n  !! declared ambiguous by fewer than two pages ({len(UNDER_DECLARED)}):")
        for n, ps in sorted(UNDER_DECLARED.items()):
            print(f"     {n:24s} only {', '.join(ps)} - so it is not ambiguous. "
                  f"Make it an alias, or drop it.")
